const std = @import("std");

const PortError = error{ InvalidNumber, OutOfRange };

fn parsePort(text: []const u8) PortError!u16 {
    const value = std.fmt.parseInt(u32, text, 10) catch return PortError.InvalidNumber;
    if (value == 0 or value > 65535) return PortError.OutOfRange;
    return @intCast(value);
}

pub fn main() void {
    std.debug.print("{any}\n", .{parsePort("8080")});
}
